      "trecho_id": "ACTION_LOG.A01",
      "rotulo": "DECISAO_HUMANA",
      "informacoes": [],
      "observacao": "A entrega do redutor em D20 continua correta, mas a folga do fornecedor passou a ser de 2 dias."
    },
    {
      "trecho_id": "ACTION_LOG.A02",
      "rotulo": "CORRETO",
      "informacoes": [],
