      "informacoes": [],
      "observacao": ""
    },
    {
      "trecho_id": "ACTION_LOG.A04",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "a partir de D25",
          "motivo": "valor_divergente",
          "correto_seria": "a partir de D27, quando o protótipo fica disponível."
        },
        {
          "citacao": "até a validação em D35",
          "motivo": "valor_divergente",
          "correto_seria": "até a validação em D37."
        },
        {
          "citacao": "o protótipo estará disponível em D26",
          "motivo": "valor_divergente",
          "correto_seria": "o protótipo estará disponível em D27."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "ACTION_LOG.A05",
      "rotulo": "DECISAO_HUMANA",
      "informacoes": [],
      "observacao": "As condições de custo continuam corretas, mas o atraso agora leva o projeto além de D40 e torna aplicável o custo excedente."
    },
    {
      "trecho_id": "ACTION_LOG.A06",
      "rotulo": "DECISAO_HUMANA",
      "informacoes": [],
      "observacao": "A mudança desloca o acoplamento para fora da janela de D16 a D20; convém decidir como tratar seu frete."
    },
    {
      "trecho_id": "RISK_REGISTER.R01",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "não tem folga",
          "motivo": "valor_divergente",
          "correto_seria": "tem 2 dias de folga: a montagem começa em D22 e o redutor chega em D20."
        },
        {
          "citacao": "qualquer atraso empurraria a montagem para depois de D20 e a liberação para depois de D40",
          "motivo": "premissa_alterada",
          "correto_seria": "Atrasos de até 2 dias na entrega do redutor não deslocam a montagem. A liberação está prevista para D42; apenas um atraso superior à folga de 2 dias deslocaria a montagem e adiaria ainda mais a liberação."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "RISK_REGISTER.R02",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "Uma entrega depois de D20 deslocaria a montagem e, com ela, levaria a validação para depois de D35.",
          "motivo": "premissa_alterada",
          "correto_seria": "A placa e o chicote têm 3 dias de folga até a montagem em D22; somente uma entrega após D22 deslocaria a montagem e a validação, atualmente prevista para D37."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "RISK_REGISTER.R03",
      "rotulo": "DECISAO_HUMANA",
      "informacoes": [],
      "observacao": "A relação entre a extensão do teste e os custos permanece correta, mas a validação-base agora ocorre em D37."
    },
    {
      "trecho_id": "RISK_REGISTER.R04",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "compras e fabricação não têm folga",
          "motivo": "valor_divergente",
          "correto_seria": "compras e fabricação têm 2 dias de folga até a montagem em D22."
        },
        {
          "citacao": "cada dia de reanálise adiaria a liberação",
          "motivo": "premissa_alterada",
          "correto_seria": "Atrasos de até 2 dias na análise não adiariam a montagem nem a liberação; atrasos superiores a 2 dias adiariam o cronograma."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "RISK_REGISTER.R05",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "terminaria em D31",
          "motivo": "valor_divergente",
          "correto_seria": "terminaria em D33, considerando o início do teste em D27 e a repetição integral de 3 dias."
        },
        {
          "citacao": "validação em D35",
          "motivo": "valor_divergente",
          "correto_seria": "validação em D37."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "RISK_REGISTER.R06",
      "rotulo": "DECISAO_HUMANA",
      "informacoes": [],
      "observacao": "A condição descrita ocorreu: o acoplamento fica disponível em D22, a montagem começa em D22 e a liberação passa de D40 para D42."
    },
